// Evaluate K_2d(L_left, L_right) -> K[4][10] stored row-major in k_out[40]
static inline void k_table_2d_eval(float L_left, float L_right, float *k_out) {
    // Precompute powers Ll[i]=L_left^i, Lr[i]=L_right^i  (i=0..6)
    float Ll[7], Lr[7];
    Ll[0] = 1.0f; Lr[0] = 1.0f;
    Ll[1] = L_left; Lr[1] = L_right;
    for (int i = 2; i <= 6; i++) {
        Ll[i] = Ll[i-1] * L_left;
        Lr[i] = Lr[i-1] * L_right;
    }
    // Monomial terms: Ll[d-a] * Lr[a] for d=0..6
    float terms[28];
    terms[0] = 1.0f;
    terms[1] = Ll[1];
    terms[2] = Lr[1];
    terms[3] = Ll[2];
    terms[4] = Ll[1] * Lr[1];
    terms[5] = Lr[2];
    terms[6] = Ll[3];
    terms[7] = Ll[2] * Lr[1];
    terms[8] = Ll[1] * Lr[2];
    terms[9] = Lr[3];
    terms[10] = Ll[4];
    terms[11] = Ll[3] * Lr[1];
    terms[12] = Ll[2] * Lr[2];
    terms[13] = Ll[1] * Lr[3];
    terms[14] = Lr[4];
    terms[15] = Ll[5];
    terms[16] = Ll[4] * Lr[1];
    terms[17] = Ll[3] * Lr[2];
    terms[18] = Ll[2] * Lr[3];
    terms[19] = Ll[1] * Lr[4];
    terms[20] = Lr[5];
    terms[21] = Ll[6];
    terms[22] = Ll[5] * Lr[1];
    terms[23] = Ll[4] * Lr[2];
    terms[24] = Ll[3] * Lr[3];
    terms[25] = Ll[2] * Lr[4];
    terms[26] = Ll[1] * Lr[5];
    terms[27] = Lr[6];

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 10; j++) {
            float sum = 0.0f;
            int base = (i * 10 + j) * 28;
            for (int t = 0; t < 28; t++) {
                sum += k_table_2d[base + t] * terms[t];
            }
            k_out[i * 10 + j] = sum;
        }
    }
}
